		{
		    if (c == 'b' || c == 'k' || c == 'u' || c == 'g'
						|| c == K_UP || c == K_PAGEUP)
		    {
			if (msg_scrolled > Rows)
			    // scroll back to show older messages
			    do_more_prompt(c);
			else
			{
