	// '/home/r' would also match '/home/rks'
	if (fnamencmp(stopdirs_v[i], path, path_len) == 0
		&& ((int)STRLEN(stopdirs_v[i]) <= path_len
		    || vim_ispathsep(stopdirs_v[i][path_len])))
