                break;
            case EBML_SINT:
                *(int64_t *) dst = syntax[i].def.i;
                break;
            case EBML_FLOAT:
                *(double *)  dst = syntax[i].def.f;
                break;
            case EBML_STR:
            case EBML_UTF8:
                // the default may be NULL
                if (syntax[i].def.s) {
