        for (int i = 0; syntax[i].id; i++) {
            void *dst = (char *)data + syntax[i].data_offset;
            switch (syntax[i].type) {
            case EBML_UINT:
                *(uint64_t *)dst = syntax[i].def.u;
                break;
            case EBML_SINT:
                *(int64_t *) dst = syntax[i].def.i;
                break;
            case EBML_FLOAT:
                *(double *)  dst = syntax[i].def.f;
                break;
            case EBML_STR:
            case EBML_UTF8:
                // the default may be NULL
                if (syntax[i].def.s) {
