static int ebml_read_sint(AVIOContext *pb, int size,
                          int64_t default_value, int64_t *num)
{
    int n = 1;

    if (size == 0) {
        *num = default_value;
        return 0;
    } else {
        *num = sign_extend(avio_r8(pb), 8);

        /* big-endian ordering; build up number */
        while (n++ < size)
            *num = ((uint64_t)*num << 8) | avio_r8(pb);
    }

    return NEEDS_CHECKING;
}

